observations=[]
def dt(s):
    if not s:return dict(asWritten=None,year=None,month=None,precision='unknown')
    y=re.search(r'\b(19\d{2}|20\d{2})\b',s)
    m=re.match(r'(\d{1,2})/(?:19|20)\d{2}$',s)
    months=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec']
    month=int(m[1]) if m else next((i+1 for i,v in enumerate(months) if s.lower().startswith(v)),None)
    return dict(asWritten=s,year=int(y[0]) if y else None,month=month,precision=('month' if month else 'year') if y else 'unknown')
def person(id,name,url,identity,rows,notes='',kind='cv',mentions=(),limits=()):
    jobs=[]
    for row in rows:
        emp,title,start,end=row
        jobs.append(dict(employerAsWritten=emp,titleAsWritten=title,start=dt(start),end=dt(end),isCurrent=True if end and end.lower() in ['present','current','pres'] else False if dt(end)['year'] else None,sourceType=kind,sourceUrl=url,checkedAt=date,evidenceNote='Opened source lists this role and the dates transcribed here. Undated titles have unknown dates; source-era Present is not independently confirmed through 2026.'))
    rec=dict(id=id,name=name,recordIds=[id],checkedAt=date,reviewer='Codex individual source review',identityBasis=identity,coverageNote='Partial career observation. All employment facts read in the opened source sections are transcribed; this does not establish a complete real-world career. '+notes,jobs=jobs,otherEmploymentMentions=[dict(employerAsWritten=e,titleAsWritten=t,sourceType=kind,sourceUrl=url,checkedAt=date,evidenceNote=n) for e,t,n in mentions],remainingUnknowns=['Unmentioned earlier, concurrent or later roles and missing appointment dates remain unknown. No first-job or continuous-sector conclusion proposed.'],accessLimitations=list(limits),sourceUrls=[url],integrationStatus='Unpublished proposal on research branch; not integrated into public history stores.')
    observations.append(rec)
